<?php
/** Mock Google HTTP only: no credentials or billable Google requests in regression checks. */
if (PHP_SAPI !== 'cli') exit;
if (!defined('WTAI_PLUGIN_URL')) define('WTAI_PLUGIN_URL', 'https://example.com/wp-content/plugins/w2a-wf/');
$original_test_options = $GLOBALS['wfag_test_options'] ?? array();
$GLOBALS['wfag_google_requests'] = array();
$url = 'https://www.google.com/maps/?query_place_id=ChIJtestprofile0001';
check(WTAI_Settings::defaults()['image_source'] === 'media_library', 'Existing sites retain the Media Library image source by default.');
check(WTAI_Settings::sanitize('image_source', 'invalid') === 'media_library' && WTAI_Settings::sanitize('image_source', 'both') === 'both', 'Image sources validate against the three supported choices.');
rejects(function () use ($url) { WTAI_GBP_Photos::profile($url); }, 'A Google API key is required before photo retrieval.');
$secret = 'wfag-test-secret-not-a-real-google-key';
$GLOBALS['wfag_test_options']['wtai_google_places_api_key'] = $secret;
$profile = WTAI_GBP_Photos::profile($url);
check($profile['id'] === 'ChIJtestprofile0001' && count($profile['photos']) === 3, 'A public link with place ID resolves the profile and all returned photos.');
check($GLOBALS['wfag_test_options']['wtai_gbp_resolved_profile'] === array('url' => $url, 'place_id' => $profile['id']), 'Only the supplied URL and permitted place ID are saved, never Google photo metadata.');
$request = $GLOBALS['wfag_google_requests'][0];
check(strpos($request['url'], $secret) === false && $request['args']['headers']['X-Goog-Api-Key'] === $secret, 'Google API credentials use a server-side header rather than image URLs.');
check(strpos(wp_json_encode(WTAI_Settings::for_import(array())), $secret) === false, 'Normal import settings never expose the separately stored Google key.');
$request_count = count($GLOBALS['wfag_google_requests']);
WTAI_GBP_Photos::profile($url);
check(count($GLOBALS['wfag_google_requests']) === $request_count, 'Repeated profile use in a single request reuses only request-local metadata.');
foreach (array('http://www.google.com/maps/', 'https://google.com.evil.test/maps/', 'https://127.0.0.1/', 'https://user@www.google.com/maps/', 'https://www.google.com:8443/maps/') as $invalid) {
    rejects(function () use ($invalid) { WTAI_GBP_Photos::profile($invalid); }, 'Unsupported hosts, HTTP, credentials, and custom ports are rejected before fetching.');
}
check(count($GLOBALS['wfag_google_requests']) === $request_count, 'Rejected profile links never trigger outbound HTTP.');
$short = WTAI_GBP_Photos::profile('https://maps.app.goo.gl/example');
check($short['id'] === 'ChIJshortresult0001', 'Google short links resolve without unrestricted redirects.');
$GLOBALS['wfag_google_redirect'] = 'https://127.0.0.1/private';
rejects(function () { WTAI_GBP_Photos::profile('https://maps.app.goo.gl/unsafe'); }, 'A short-link redirect to a non-Google address is blocked.');
unset($GLOBALS['wfag_google_redirect']);
$named = WTAI_GBP_Photos::profile('https://www.google.com/maps/place/Test+Business/@14.500,121.000,12z');
check($named['id'] === 'ChIJsearchresult0001', 'Named Maps links use Text Search with the available geographic bias.');
$GLOBALS['wfag_google_search'] = array(array('id' => 'ChIJambiguous0001'), array('id' => 'ChIJambiguous0002'));
rejects(function () { WTAI_GBP_Photos::profile('https://www.google.com/maps/place/Ambiguous+Business/'); }, 'Ambiguous profile lookup never silently chooses another business.');
unset($GLOBALS['wfag_google_search']);
$html = WTAI_GBP_Photos::shortcode(array('place' => $profile['id'], 'slot' => 0));
check(strpos($html, 'https://lh3.googleusercontent.com/places/fresh-image') !== false, 'Live rendering resolves a fresh Google-hosted photo URI.');
check(strpos($html, 'Photo &amp; Author') !== false && strpos($html, '/maps/contrib/example') !== false && strpos($html, 'google-maps-logo.svg') !== false, 'Photo author attribution, author link, avatar, and official Google Maps logo are rendered.');
check(strpos($html, $secret) === false && DONOTCACHEPAGE === true, 'Rendered photos disclose no API key and mark the page as non-cacheable.');
check(WTAI_GBP_Photos::shortcode(array('place' => '../escape', 'slot' => 0)) === '' && WTAI_GBP_Photos::shortcode(array('place' => $profile['id'], 'slot' => 100)) === '', 'Tampered resource IDs and out-of-range photo slots produce no output.');
$GLOBALS['wfag_google_photo_uri'] = 'https://example.com/not-google.jpg';
check(WTAI_GBP_Photos::shortcode(array('place' => $profile['id'], 'slot' => 1)) === '', 'Non-Google media URLs are rejected.');
unset($GLOBALS['wfag_google_photo_uri']);
$body = str_repeat('<p>' . str_repeat('Orchard trees orchard. ', 20) . '</p>', 9);
$tail = '<h2>Conclusion</h2><p>Orchard summary.</p>';
$settings = array('image_source' => 'gbp', 'gbp_profile_url' => $url, 'max_images_per_post' => 3);
$matcher = new WTAI_Image_Matcher();
$output = $matcher->insert_images($body . $tail, $settings, 'Orchard');
check($matcher->get_report()['inserted'] === 3 && substr_count($output, '[wtai_gbp_photo ') === 3, 'GBP-only placement fills three slots without needing Media Library entries.');
check(array_column($matcher->get_report()['placements'], 'actual_percent') === array(33.3, 66.7, 100.0), 'GBP placeholders keep the requested word-percentage spacing.');
check(substr($output, strpos($output, '<h2>Conclusion')) === $tail, 'GBP images stay entirely before Conclusion.');
check(strpos($output, $secret) === false && strpos($output, 'fresh-image') === false && strpos($output, '/photos/photo') === false, 'Stored article placeholders contain no credentials, expiring photo URLs, or Google photo references.');
check($matcher->insert_images($output, $settings, 'Orchard') === $output, 'Repeated processing never repeats existing GBP slots.');
check(strpos(WTAI_GBP_Photos::preview($output), '[wtai_gbp_photo ') === false, 'Image previews render only this plugin\'s generated Google photo placeholders.');
$GLOBALS['wfag_test_media'] = array(1 => array('title' => 'Orchard', 'alt' => 'Orchard', 'caption' => '', 'description' => ''));
WTAI_Media_Index::invalidate();
$settings['image_source'] = 'both';
$mixed = $matcher->insert_images($body, $settings, 'Orchard');
check($matcher->get_report()['inserted'] === 3 && strpos($mixed, 'wp-image-1') !== false && strpos($mixed, '[wtai_gbp_photo ') !== false, 'Both sources share a single image maximum and placement plan.');
$GLOBALS['wfag_google_failure'] = array('response' => array('code' => 403), 'body' => '{"error":"sensitive diagnostics"}');
$settings['gbp_profile_url'] = 'https://www.google.com/maps/?query_place_id=ChIJfailedprofile0001';
$fallback = $matcher->insert_images($body, $settings, 'Orchard');
check($matcher->get_report()['inserted'] === 1 && strpos($fallback, 'wp-image-1') !== false, 'Both mode retains relevant library images when Google requests fail.');
check(strpos($matcher->get_report()['message'], 'HTTP 403') !== false && strpos($matcher->get_report()['message'], 'sensitive diagnostics') === false, 'Failures explain the HTTP status without disclosing raw Google diagnostics.');
$settings['image_source'] = 'gbp';
check($matcher->insert_images($body, $settings, 'Orchard') === $body && $matcher->get_report()['inserted'] === 0, 'GBP-only failure still preserves and imports the article without images.');
check(WTAI_GBP_Photos::shortcode(array('place' => 'ChIJfailedprofile0001', 'slot' => 0)) === '', 'Google outages never break public article rendering.');
unset($GLOBALS['wfag_google_failure'], $GLOBALS['wfag_test_media']);
WTAI_Media_Index::invalidate();
$GLOBALS['wfag_test_options'] = $original_test_options;
